"""Build an offline selector for the eight module sheets, with zoom and file links."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "docs/dbdiagram/modules"


def main():
    manifest = json.loads((OUT / "manifest.json").read_text(encoding="utf-8"))
    renders = json.loads((OUT / "render-validation.json").read_text(encoding="utf-8"))
    assert renders["all_passed"]
    data = []
    for m in manifest["modules"]:
        render = next(r for r in renders["modules"] if r["slug"] == m["slug"])
        data.append({**m, "width": render["width"], "height": render["height"]})
    html = r'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>8 sơ đồ CSDL theo nghiệp vụ · Quản lý nhà trọ</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2f6;color:#172033;font:14px Arial,sans-serif}header{height:88px;padding:20px 24px;background:#fff;border-bottom:1px solid #dce3eb;display:flex;align-items:center;justify-content:space-between;gap:16px}h1{font-size:20px;margin:0 0 7px}header p{color:#64748b;margin:0;font-size:13px}a,button{font:inherit}a{color:#315775;text-decoration:none}.toplinks{display:flex;gap:10px;align-items:center}.toplinks a,button,.downloads a{border:1px solid #d4dce6;background:#fff;border-radius:6px;padding:9px 12px;color:#334155;cursor:pointer}.toplinks a.primary{background:#315775;color:#fff;border-color:#315775}.layout{display:grid;grid-template-columns:264px 1fr;height:calc(100vh - 88px)}aside{background:#fff;border-right:1px solid #dce3eb;padding:20px 12px;overflow:auto}.side-caption{font-size:11px;color:#64748b;letter-spacing:1px;padding:0 10px;margin-bottom:13px}aside button{display:block;width:100%;text-align:left;margin:0 0 7px;padding:12px 11px;border:1px solid transparent}aside button:hover{background:#f8fafc}aside button[aria-current="true"]{border-color:#c7d7e6;background:#edf4fa}aside strong{display:block;font-size:13px;color:#172033}aside small{display:block;color:#64748b;font-size:11px;margin:6px 0 0 23px}.side-note{font-size:12px;line-height:1.6;color:#64748b;margin:22px 10px 0}.workspace{min-width:0;min-height:0;display:flex;flex-direction:column}.bar{min-height:68px;padding:12px 20px;background:#f8fafc;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid #dce3eb;flex-wrap:wrap}.bar h2{font-size:15px;margin:0 0 5px}.bar p{font-size:12px;margin:0;color:#64748b}.controls,.downloads{display:flex;align-items:center;gap:7px}.controls output{width:48px;text-align:center;font-size:12px}.viewport{flex:1;min-height:0;overflow:auto;padding:22px;outline:none}.paper{position:relative;margin:auto;background:white;box-shadow:0 4px 20px #2438541a}.paper iframe{display:block;position:absolute;left:0;top:0;border:0;transform-origin:0 0;pointer-events:none}.key{font-size:12px;color:#64748b;padding:9px 20px;background:#fff;border-top:1px solid #dce3eb}button:focus-visible,a:focus-visible{outline:2px solid #2563eb;outline-offset:2px}@media(max-width:950px){.layout{grid-template-columns:210px 1fr}header{padding:15px}.toplinks a{padding:8px}.toplinks .total{display:none}.bar{padding:10px}.side-note{font-size:11px}}@media(max-width:650px){.layout{grid-template-columns:1fr}aside{display:flex;gap:6px;padding:8px;height:72px;border-bottom:1px solid #dce3eb}aside button{min-width:180px;margin:0}aside .side-note,.side-caption{display:none}.workspace{height:calc(100vh - 160px)}header h1{font-size:16px}.toplinks{gap:4px}.toplinks a{font-size:11px}header p{font-size:11px}aside small{display:none}}
</style></head><body><header><div><h1>CSDL quản lý nhà trọ · 8 sơ đồ nghiệp vụ</h1><p>49 bảng chính · 455 cột · 151 khóa ngoại · PostgreSQL / V13</p></div><nav class="toplinks" aria-label="Tài liệu"><a href="../index.html" class="total">Bản tổng</a><a href="README.md">Quy ước</a><a href="8-so-do-nghiep-vu.zip" download class="primary">Tải 8 PDF</a></nav></header>
<main class="layout"><aside aria-label="Chọn sơ đồ nghiệp vụ"><div class="side-caption">8 PHẦN CỦA CÙNG CSDL</div><nav id="modules"></nav><p class="side-note">Bảng có màu: hiện đủ cột.<br>Bảng xám: bản tham chiếu rút gọn, lặp lại để đọc liên kết; không phải bảng mới.<br><br>Không cộng các bản tham chiếu vào 49 bảng chính.</p></aside><section class="workspace"><div class="bar"><div><h2 id="title"></h2><p id="stats"></p></div><div class="controls"><button id="fit">Vừa màn hình</button><button id="less" aria-label="Thu nhỏ">−</button><output id="zoom" aria-live="polite"></output><button id="more" aria-label="Phóng to">+</button><button id="actual">100%</button></div><nav class="downloads" aria-label="Tải phần đang xem"><a id="pdf" target="_blank">PDF ↗</a><a id="dbml" download>DBML</a><a id="svg" target="_blank">SVG ↗</a></nav></div><div class="viewport" id="viewport" tabindex="0" aria-label="Sơ đồ đang chọn"><div class="paper" id="paper"><iframe id="diagram" title="Sơ đồ nghiệp vụ" tabindex="-1"></iframe></div></div><div class="key">Giữ đủ cột của bảng chính và FK thật có bảng nguồn trong nhóm. Mở PDF để xem hoặc gửi từng phần.</div></section></main>
<script>
const data=__DATA__;const area=document.getElementById('viewport'),paper=document.getElementById('paper'),frame=document.getElementById('diagram');let active,scale=1;
function zoom(value,center=true){const old=scale,x=(area.scrollLeft+area.clientWidth/2)/old,y=(area.scrollTop+area.clientHeight/2)/old;scale=Math.max(.2,Math.min(2.5,value));paper.style.width=active.width*scale+'px';paper.style.height=active.height*scale+'px';frame.style.transform='scale('+scale+')';document.getElementById('zoom').textContent=Math.round(scale*100)+'%';if(center){area.scrollLeft=x*scale-area.clientWidth/2;area.scrollTop=y*scale-area.clientHeight/2}}
function fit(){zoom(Math.min((area.clientWidth-50)/active.width,(area.clientHeight-50)/active.height),false);area.scrollTo(0,0)}
function select(slug){const m=data.find(m=>m.slug===slug)||data[0];active=m;document.querySelectorAll('#modules button').forEach(b=>b.setAttribute('aria-current',String(b.dataset.slug===m.slug)));document.getElementById('title').textContent=String(m.number).padStart(2,'0')+' · '+m.title;document.getElementById('stats').textContent=m.owned_tables.length+' bảng chính · '+m.context_tables.length+' tham chiếu rút gọn · '+m.foreign_keys.length+' FK';for(const type of ['pdf','dbml','svg'])document.getElementById(type).href=m.slug+'.'+type;frame.width=m.width;frame.height=m.height;frame.src=m.slug+'.html';fit();history.replaceState(null,'','#'+m.slug)}
for(const m of data){const b=document.createElement('button');b.dataset.slug=m.slug;b.innerHTML='<strong>'+String(m.number).padStart(2,'0')+' · '+m.title+'</strong><small>'+m.owned_tables.length+' bảng chính · '+m.foreign_keys.length+' FK</small>';b.onclick=()=>select(m.slug);document.getElementById('modules').append(b)}
document.getElementById('fit').onclick=fit;document.getElementById('less').onclick=()=>zoom(scale/1.2);document.getElementById('more').onclick=()=>zoom(scale*1.2);document.getElementById('actual').onclick=()=>zoom(1);window.onresize=fit;window.addEventListener('hashchange',()=>select(location.hash.slice(1)));select(location.hash.slice(1));
</script></body></html>'''
    (OUT / "index.html").write_text(html.replace("__DATA__", json.dumps(data, ensure_ascii=False)), encoding="utf-8", newline="\n")
    print("Built docs/dbdiagram/modules/index.html")


if __name__ == "__main__":
    main()
